 1→// Shared plan constants — safe for both client and server
 2→
 3→export const PLAN_FREE = "free";
 4→export const PLAN_PRO_MONTHLY = "Pro Monthly";
 5→export const PLAN_PRO_ANNUAL = "Pro Annual";
 6→export const PLAN_ULTIMATE_MONTHLY = "Ultimate Monthly";
 7→export const PLAN_ULTIMATE_ANNUAL = "Ultimate Annual";
 8→
 9→export const ALL_PAID_PLANS = [
10→  PLAN_PRO_MONTHLY,
11→  PLAN_PRO_ANNUAL,
12→  PLAN_ULTIMATE_MONTHLY,
13→  PLAN_ULTIMATE_ANNUAL,
14→];
15→
16→export const PLAN_LIMITS = {
17→  free: { maxZipCodes: 25, allowBlocked: false, label: "Free" },
18→  pro: { maxZipCodes: Infinity, allowBlocked: true, label: "Pro" },
19→  ultimate: { maxZipCodes: Infinity, allowBlocked: true, label: "Ultimate" },
20→};
21→
22→export function getPlanTier(planName: string): "free" | "pro" | "ultimate" {
23→  if (planName === PLAN_PRO_MONTHLY || planName === PLAN_PRO_ANNUAL)
24→    return "pro";
25→  if (planName === PLAN_ULTIMATE_MONTHLY || planName === PLAN_ULTIMATE_ANNUAL)
26→    return "ultimate";
27→  return "free";
28→}
