100→// ─── Loader ───────────────────────────────────────────────────────────────────
101→
102→export const loader = async ({ request }: LoaderFunctionArgs) => {
103→  const { session, billing } = await authenticate.admin(request);
104→  const shop = session.shop;
105→
106→  try {
107→    /* eslint-disable @typescript-eslint/no-explicit-any */
108→    const billingCheck = await billing.check({
109→      plans: ALL_PAID_PLANS as any,
110→      isTest: process.env.NODE_ENV !== "production",
111→    });
112→    /* eslint-enable @typescript-eslint/no-explicit-any */
113→    const subscription = await syncSubscriptionFromShopify(
114→      shop,
115→      billingCheck.appSubscriptions ?? [],
116→    );
117→    return { subscription };
118→  } catch {
119→    const subscription = await getShopSubscription(shop);
120→    return { subscription };
121→  }
122→};
